  parseFSharpPipelineBody(this: Parser, prec: number): N.Expression {
    const startLoc = this.state.startLoc;

    this.state.potentialArrowAt = this.state.start;
    const oldInFSharpPipelineDirectBody = this.state.inFSharpPipelineDirectBody;
    this.state.inFSharpPipelineDirectBody = true;

    const body = this.parseMaybeUnaryOrPrivate();

    // A solo `await` cannot be mixed with a binary operator (e.g.
    // `x |> await && y` or `x |> await ** y`); the pipeline must be
    // parenthesized instead. The pipeline operator itself and `in` inside a
    // for-in head are not treated as such an operator.
    if (
      body.type === "AwaitExpression" &&
      !body.argument &&
      tokenIsOperator(this.state.type) &&
      this.state.type !== tt.pipeline &&
      (this.prodParam.hasIn || !this.match(tt._in))
    ) {
      this.raise(Errors.PipelineBodySoloAwaitBinary, body);
    }

    const ret = this.parseExprOp(body, startLoc, prec);

